from ta_emss.utilities.trs.commands.emssim import EmssimCommand


class Rtpm_deactivate(EmssimCommand):
    def __init__(self, method="rtpm_deactivate", timeout=60, rpc_connection_name='localRPC'):
        super(Rtpm_deactivate, self).__init__(method, timeout, rpc_connection_name)
        self.params = None

    def on_new_data(self, **data):
        data = super(Rtpm_deactivate, self).on_new_data(**data)
        if "msg" in data:
            if (data["msg"] == "Validation completed, activating plan file"):
                self._ret['validation'] = "completed"
            elif (data["msg"] == "Validation Errors"):
                self._ret['error_table'] = data["tables"]
                self._ret['verror'] = data["errors"]
                self._ret['validation'] = "failed"
            elif (data["msg"] == "Activation completed"):
                self._ret['activation'] = "completed"
            elif (data["msg"] == "Activation Errors"):
                self._ret['table'] = data["tables"]
                self._ret['activation_error'] = data["errors"]
                self._ret['activation'] = "failed"
        elif ("status" in data):
            self._ret["status"] = data["status"]
